package cli

import (
	"fmt"
	"io"
	"os"
	"path/filepath"

	skills "github.com/jdbencardinop/tesseraworkspaces/assets/skills"
	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func addCmd() *cobra.Command {
	var templates []string
	var newBranch string
	var base string
	var open bool
	var force bool
	var useTmux bool

	cmd := &cobra.Command{
		Use:   "add <feature>",
		Short: "Create a feature workspace",
		Long: `Create a feature workspace with an inject/ directory for shared files.

Files in inject/ are symlinked into every worktree. Use -n to also
create a first worktree branch, and --open to launch the agent.

Note: injected files appear as untracked in git status. Add them to
.gitignore or place them in an already-ignored subfolder.`,
		Args: cobra.ExactArgs(1),
		Run: func(cmd *cobra.Command, args []string) {
			feature := args[0]
			root := internal.FeaturePath(feature)

			wsRoot := internal.TwsRoot()
			internal.Must(os.MkdirAll(filepath.Join(wsRoot, ".tws-workspace"), 0755))
			internal.Must(os.MkdirAll(filepath.Join(root, "worktrees"), 0755))
			internal.Must(os.WriteFile(filepath.Join(root, "FEATURE.md"), []byte("# "+feature+"\n"), 0644))

			// Create inject/ dir
			injectDir := internal.InjectPath(root)
			internal.Must(os.MkdirAll(injectDir, 0755))

			// Apply templates
			applyTemplates(injectDir, templates)

			// Add default CLAUDE.local.md if not provided by any template
			claudeLocal := filepath.Join(injectDir, "CLAUDE.local.md")
			if _, err := os.Stat(claudeLocal); os.IsNotExist(err) {
				internal.Must(os.WriteFile(claudeLocal, []byte("# "+feature+" - shared context\n\nThis file is symlinked into every worktree for this feature.\nEdit it in the workspace inject/ directory.\n"), 0644))
			}

			// Install orchestrator skill in the feature dir
			orchPath := filepath.Join(root, ".claude", "skills", "tesseraworkspaces-orchestrator", "SKILL.md")
			installFile(orchPath, skills.ClaudeOrchestratorSkill, false)

			fmt.Println("Feature added:", feature)

			// Quick start: create worktree if -n specified
			if newBranch != "" {
				if !cmd.Flags().Changed("base") {
					base = internal.DefaultBranch()
				}
				createWorktree(feature, newBranch, base, "", force)

				if open {
					path := internal.WorktreePath(feature, newBranch)
					if useTmux {
						openWithTmux(feature, newBranch, path)
					} else {
						openDirect(path)
					}
				}
			}
		},
	}

	cmd.Flags().StringArrayVar(&templates, "template", nil, "Template directory to copy into inject/ (can be specified multiple times)")
	cmd.Flags().StringVarP(&newBranch, "new", "n", "", "Also create a worktree branch")
	cmd.Flags().StringVar(&base, "base", "", "Base branch for the new worktree (default: repo's default branch)")
	cmd.Flags().BoolVar(&open, "open", false, "Open the worktree after creation (used with -n)")
	cmd.Flags().BoolVarP(&force, "force", "f", false, "Force checkout of already checked-out branch")
	cmd.Flags().BoolVar(&useTmux, "tmux", false, "Open in tmux session (used with --open)")

	return cmd
}

// applyTemplates copies files from the configured template dir and any
// explicit --template dirs into the inject directory.
func applyTemplates(injectDir string, extraTemplates []string) {
	// Configured default template first
	defaultTemplate := internal.TemplatePath()
	if defaultTemplate != "" {
		count, err := copyDir(defaultTemplate, injectDir)
		if err != nil {
			fmt.Printf("Warning: default template copy failed: %v\n", err)
		} else if count > 0 {
			fmt.Printf("Copied %d file(s) from default template\n", count)
		}
	}

	// Then explicit --template dirs (layered in order)
	for _, tmplDir := range extraTemplates {
		info, err := os.Stat(tmplDir)
		if err != nil || !info.IsDir() {
			fmt.Printf("Warning: template directory not found: %s\n", tmplDir)
			continue
		}
		count, err := copyDir(tmplDir, injectDir)
		if err != nil {
			fmt.Printf("Warning: template copy failed for %s: %v\n", tmplDir, err)
		} else if count > 0 {
			fmt.Printf("Copied %d file(s) from %s\n", count, tmplDir)
		}
	}
}

// copyDir copies all files from src to dst, preserving directory structure.
// Does not overwrite existing files. Returns the count of files copied.
func copyDir(src, dst string) (int, error) {
	count := 0
	err := filepath.Walk(src, func(srcPath string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}

		relPath, err := filepath.Rel(src, srcPath)
		if err != nil {
			return err
		}
		if relPath == "." {
			return nil
		}

		dstPath := filepath.Join(dst, relPath)

		if info.IsDir() {
			return os.MkdirAll(dstPath, 0755)
		}

		// Skip if exists (conflict resolution is a separate feature)
		if _, err := os.Stat(dstPath); err == nil {
			fmt.Printf("  skip: %s (exists)\n", relPath)
			return nil
		}

		// Copy file
		in, err := os.Open(srcPath)
		if err != nil {
			return err
		}
		defer in.Close() //nolint:errcheck

		out, err := os.Create(dstPath)
		if err != nil {
			return err
		}
		defer out.Close() //nolint:errcheck

		if _, err := io.Copy(out, in); err != nil {
			return err
		}
		count++
		return nil
	})
	return count, err
}

package cli

import (
	"fmt"
	"os"
	"os/exec"
	"strings"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func newCmd() *cobra.Command {
	var base string
	var force bool
	var repo string

	cmd := &cobra.Command{
		Use:   "new <feature> <branch>",
		Short: "Create a worktree branch",
		Args:  cobra.ExactArgs(2),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			switch len(args) {
			case 0:
				return internal.ListFeatures(), cobra.ShellCompDirectiveNoFileComp
			case 1:
				return internal.ListBranches(args[0]), cobra.ShellCompDirectiveNoFileComp
			default:
				return nil, cobra.ShellCompDirectiveNoFileComp
			}
		},
		Run: func(cmd *cobra.Command, args []string) {
			if !cmd.Flags().Changed("base") {
				base = internal.DefaultBranch()
			}
			createWorktree(args[0], args[1], base, repo, force)
		},
	}

	cmd.Flags().StringVar(&base, "base", "", "Parent branch for stacking (default: repo's default branch)")
	cmd.Flags().BoolVarP(&force, "force", "f", false, "Force checkout of already checked-out branch")
	cmd.Flags().StringVar(&repo, "repo", "", "Source repository path (for cross-repo worktrees)")

	return cmd
}

// createWorktree is the shared logic for creating a worktree branch.
// Used by both tws new and tws add -n.
// repoPath is the source repo (empty = current repo).
func createWorktree(feature, branch, base, repoPath string, force bool) {
	internal.RequireTool("git")

	featurePath := internal.FeaturePath(feature)
	path := internal.WorktreePath(feature, branch)

	internal.Must(os.MkdirAll(featurePath, 0755))

	// Determine which repo to use
	var repoRoot string
	if repoPath != "" {
		// Cross-repo: use the specified repo
		absRepo, err := internal.AbsPath(repoPath)
		if err != nil {
			fmt.Printf("Error: invalid repo path %s: %v\n", repoPath, err)
			os.Exit(1)
		}
		repoRoot = absRepo
		repoPath = absRepo
	} else {
		// Default: use the current repo
		root, err := internal.MainRepoRoot()
		if err != nil {
			fmt.Println("Error: must be run from inside a git repository")
			os.Exit(1)
		}
		repoRoot = root
	}

	// Check if branch exists in the target repo
	branchExists := internal.RunSilent("git", "-C", repoRoot, "rev-parse", "--verify", branch) == nil

	if branchExists {
		if isCheckedOutIn(repoRoot, branch) && !force {
			fmt.Printf("Warning: branch %q is already checked out in another worktree.\n", branch)
			fmt.Println("Use --force to check it out anyway.")
			os.Exit(1)
		}

		gitArgs := []string{"worktree", "add"}
		if force {
			gitArgs = append(gitArgs, "--force")
		}
		gitArgs = append(gitArgs, path, branch)
		internal.Must(internal.RunDir(repoRoot, "git", gitArgs...))
	} else {
		internal.Must(internal.RunDir(repoRoot, "git", "worktree", "add", path, "-b", branch))
	}

	stack, _ := internal.LoadStack(featurePath)
	if !internal.HasBranch(stack, branch) {
		stack.Branches = append(stack.Branches, internal.StackEntry{
			Name: branch,
			Base: base,
			Repo: repoPath,
		})
		internal.Must(internal.SaveStack(featurePath, stack))
	}

	// Inject shared files into the worktree
	target := internal.ResolveInjectInto("")
	if err := internal.InjectFiles(featurePath, path, target); err != nil {
		fmt.Printf("Warning: inject failed: %v\n", err)
	}

	// Auto-install hooks if configured
	cfg := internal.LoadConfig()
	if cfg.AutoHooks != nil && *cfg.AutoHooks {
		if err := installHooksForWorktree(path, feature); err != nil {
			fmt.Printf("Warning: auto-hooks install failed: %v\n", err)
		}
	}

	if repoPath != "" {
		fmt.Printf("Worktree created: %s (base: %s, repo: %s)\n", path, base, repoPath)
	} else {
		fmt.Printf("Worktree created: %s (base: %s)\n", path, base)
	}
}

// isCheckedOutIn checks if a branch is checked out in any worktree of the given repo.
func isCheckedOutIn(repoDir, branch string) bool {
	out, err := exec.Command("git", "-C", repoDir, "worktree", "list", "--porcelain").Output()
	if err != nil {
		return false
	}
	for _, line := range strings.Split(string(out), "\n") {
		if strings.TrimSpace(line) == "branch refs/heads/"+branch {
			return true
		}
	}
	return false
}

package cli

import (
	"fmt"
	"os"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func renameCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "rename",
		Short: "Rename a feature or branch",
	}

	cmd.AddCommand(renameFeatureCmd())
	cmd.AddCommand(renameBranchCmd())

	return cmd
}

func renameFeatureCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "feature <old-name> <new-name>",
		Short: "Rename a feature",
		Args:  cobra.ExactArgs(2),
		Run: func(cmd *cobra.Command, args []string) {
			oldName := args[0]
			newName := args[1]

			oldPath := internal.FeaturePath(oldName)
			newPath := internal.FeaturePath(newName)

			if _, err := os.Stat(oldPath); os.IsNotExist(err) {
				fmt.Printf("Feature not found: %s\n", oldName)
				os.Exit(1)
			}

			if _, err := os.Stat(newPath); err == nil {
				fmt.Printf("Feature already exists: %s\n", newName)
				os.Exit(1)
			}

			if err := os.Rename(oldPath, newPath); err != nil {
				fmt.Printf("Error renaming: %v\n", err)
				os.Exit(1)
			}

			fmt.Printf("Renamed feature: %s → %s\n", oldName, newName)
		},
	}
}

func renameBranchCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "branch <feature> <old-name> <new-name>",
		Short: "Rename a branch within a feature",
		Args:  cobra.ExactArgs(3),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			switch len(args) {
			case 0:
				return internal.ListFeatures(), cobra.ShellCompDirectiveNoFileComp
			case 1:
				return internal.ListBranches(args[0]), cobra.ShellCompDirectiveNoFileComp
			default:
				return nil, cobra.ShellCompDirectiveNoFileComp
			}
		},
		Run: func(cmd *cobra.Command, args []string) {
			internal.RequireTool("git")

			feature := args[0]
			oldName := args[1]
			newName := args[2]

			featurePath := internal.FeaturePath(feature)

			// Load stack (don't mutate yet)
			stack, err := internal.LoadStack(featurePath)
			if err != nil {
				fmt.Printf("No stack.yaml found for feature: %s\n", feature)
				os.Exit(1)
			}

			if !internal.HasBranch(stack, oldName) {
				fmt.Printf("Branch %q not found in stack\n", oldName)
				os.Exit(1)
			}

			// Resolve git context: find an active worktree to run git from
			gitDir := resolveGitDir(featurePath, stack)
			if gitDir == "" {
				fmt.Println("Error: could not find a git context. Run from inside the repo or ensure at least one active worktree exists.")
				os.Exit(1)
			}

			// Step 1: Git operations FIRST (validate before mutating metadata)
			oldPath := internal.WorktreePath(feature, oldName)
			newPath := internal.WorktreePath(feature, newName)

			if _, err := os.Stat(oldPath); err == nil {
				// Active worktree: remove, rename branch, re-add
				if err := internal.RunDir(gitDir, "git", "worktree", "remove", "--force", oldPath); err != nil {
					fmt.Printf("Error removing worktree: %v\n", err)
					os.Exit(1)
				}
				if err := internal.RunDir(gitDir, "git", "branch", "-m", oldName, newName); err != nil {
					// Rollback: re-add old worktree
					_ = internal.RunDir(gitDir, "git", "worktree", "add", oldPath, oldName)
					fmt.Printf("Error renaming git branch: %v\n", err)
					os.Exit(1)
				}
				if err := internal.RunDir(gitDir, "git", "worktree", "add", newPath, newName); err != nil {
					fmt.Printf("Error creating new worktree: %v\n", err)
					os.Exit(1)
				}

				// Re-inject files into the new worktree
				target := internal.ResolveInjectInto("")
				if injectErr := internal.InjectFiles(featurePath, newPath, target); injectErr != nil {
					fmt.Printf("Warning: inject failed: %v\n", injectErr)
				}
			} else {
				// Archived: just rename the git branch
				if err := internal.RunDir(gitDir, "git", "branch", "-m", oldName, newName); err != nil {
					fmt.Printf("Error renaming git branch: %v\n", err)
					os.Exit(1)
				}
			}

			// Step 2: NOW mutate metadata (git succeeded)
			internal.RenameBranch(&stack, oldName, newName)
			internal.Must(internal.SaveStack(featurePath, stack))

			// Kill stale tmux session
			oldSession := sanitizeSessionName(feature + "/" + oldName)
			if sessionExists(oldSession) {
				_ = internal.RunSilent("tmux", "kill-session", "-t", oldSession)
			}

			// Update decisions.yaml branch references
			decisions, err := internal.LoadDecisions(featurePath)
			if err == nil {
				for i := range decisions.Entries {
					if decisions.Entries[i].Branch == oldName {
						decisions.Entries[i].Branch = newName
					}
				}
				_ = internal.SaveDecisions(featurePath, decisions)
			}

			fmt.Printf("Renamed branch: %s → %s (in feature %s)\n", oldName, newName, feature)
		},
	}
}

// resolveGitDir finds a usable git directory from the feature's worktrees.
// Returns the path to an active worktree, or tries cwd as fallback.
func resolveGitDir(featurePath string, stack internal.Stack) string {
	// Try active worktrees first
	for _, entry := range stack.Branches {
		wtPath := internal.WorktreePath("", entry.Name)
		// Reconstruct from featurePath directly
		path := featurePath + "/worktrees/" + entry.Name
		if _, err := os.Stat(path); err == nil {
			return path
		}
		if entry.Repo != "" {
			return entry.Repo
		}
		_ = wtPath
	}

	// Fallback: try cwd
	if internal.BranchExists("HEAD") {
		cwd, _ := os.Getwd()
		return cwd
	}

	return ""
}

package cli

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
)

func syncWithStack(feature, featurePath string, stack internal.Stack, sorted []internal.StackEntry) {
	syncWithStackFiltered(feature, featurePath, stack, sorted, nil)
}

func syncWithStackFiltered(feature, featurePath string, stack internal.Stack, sorted []internal.StackEntry, alreadyDone map[string]bool) {
	skipped := make(map[string]bool)
	updatedByRef := make(map[string]bool)
	completed := make([]string, 0)

	// Collect already-done branches from --continue
	if alreadyDone == nil {
		alreadyDone = make(map[string]bool)
	}

	// Pass 1: rebase active branches with --update-refs
	for _, entry := range sorted {
		if skipped[entry.Name] || alreadyDone[entry.Name] {
			continue
		}

		path := internal.WorktreePath(feature, entry.Name)
		if _, err := os.Stat(path); os.IsNotExist(err) {
			continue
		}

		// Health check: verify worktree is on the expected branch
		if issue := internal.CheckWorktreeBranch(path, entry.Name); issue != nil {
			fmt.Println(formatSyncStatus(entry.Name, "active", "wrong-branch"))
			fmt.Printf("    %s\n", issue.Problem)
			fmt.Printf("    %s\n", issue.Hint)
			skipDescendants(stack, entry.Name, skipped)
			continue
		}

		base := resolveBase(entry.Base)

		// Determine git context for resolving SHAs
		gitContext := path
		if entry.Repo != "" {
			gitContext = entry.Repo
		}

		// Build rebase args — use --onto if we have a previous base SHA
		// to avoid ghost conflicts from amended commits
		var rebaseArgs []string
		currentBaseSHA := internal.GetBranchSHA(gitContext, base)
		if entry.LastBaseSHA != "" && currentBaseSHA != "" && entry.LastBaseSHA != currentBaseSHA {
			// Base has changed (amended/rebased) — use --onto to skip stale commits
			rebaseArgs = []string{"rebase", "--update-refs", "--onto", base, entry.LastBaseSHA}
		} else {
			rebaseArgs = []string{"rebase", "--update-refs", base}
		}

		err := internal.RunDirClean(path, "git", rebaseArgs...)
		if err != nil {
			fmt.Println(formatSyncStatus(entry.Name, "active", "conflict"))

			// Collect pending branches
			pending := collectPending(sorted, entry.Name, skipped, alreadyDone, completed)
			skippedList := collectSkippedNames(stack, entry.Name)

			// Save state for --continue
			state := internal.NewSyncState()
			state.FailedBranch = entry.Name
			state.Pending = pending
			state.Completed = completed
			state.Skipped = skippedList
			_ = internal.SaveSyncState(featurePath, state)

			fmt.Printf("    Resolve conflicts in: %s\n", path)
			fmt.Println("    Then run: git add . && git rebase --continue")
			fmt.Printf("    Resume with: tws sync %s --continue\n", feature)
			skipDescendants(stack, entry.Name, skipped)
			return
		}

		// Post-rebase validation
		if !runValidation(path, entry.Name) {
			skipDescendants(stack, entry.Name, skipped)
		} else {
			fmt.Println(formatSyncStatus(entry.Name, "active", "synced"))
			markUpdatedAncestors(stack, entry.Name, featurePath, updatedByRef)
			completed = append(completed, entry.Name)

			// Update last_base_sha for next sync
			newBaseSHA := internal.GetBranchSHA(gitContext, base)
			if newBaseSHA != "" {
				internal.UpdateBaseSHA(&stack, entry.Name, newBaseSHA)
				_ = internal.SaveStack(featurePath, stack)
			}
		}
	}

	// Pass 2: handle archived/missing branches
	for _, entry := range sorted {
		if skipped[entry.Name] || alreadyDone[entry.Name] {
			if skipped[entry.Name] {
				fmt.Println(formatSyncStatus(entry.Name, "skipped", "skipped"))
			}
			continue
		}

		path := internal.WorktreePath(feature, entry.Name)
		if _, err := os.Stat(path); err == nil {
			continue
		}

		if internal.IsPrunableWorktree(entry.Name) {
			fmt.Printf("  [?] %s (missing — stale worktree ref, run: tws archive %s %s or tws new %s %s)\n",
				entry.Name, feature, entry.Name, feature, entry.Name)
			continue
		}

		if updatedByRef[entry.Name] {
			fmt.Println(formatSyncStatus(entry.Name, "archived", "synced"))
			continue
		}

		base := resolveBase(entry.Base)

		rebaseDir := ""
		if entry.Repo != "" {
			rebaseDir = entry.Repo
		}

		var rebaseErr error
		if rebaseDir != "" {
			rebaseErr = internal.RunSilentDir(rebaseDir, "git", "rebase", base, entry.Name)
		} else {
			rebaseErr = internal.RunSilent("git", "rebase", base, entry.Name)
		}

		if rebaseErr != nil {
			if rebaseDir != "" {
				_ = internal.RunSilentDir(rebaseDir, "git", "rebase", "--abort")
			} else {
				_ = internal.RunSilent("git", "rebase", "--abort")
			}
			fmt.Println(formatSyncStatus(entry.Name, "archived", "conflict"))
			fmt.Printf("    Restore with: tws new %s %s\n", feature, entry.Name)
			skipDescendants(stack, entry.Name, skipped)
		} else {
			fmt.Println(formatSyncStatus(entry.Name, "archived", "synced"))
		}
	}

	// Clean up state if we completed everything
	internal.DeleteSyncState(featurePath)
}

func collectPending(sorted []internal.StackEntry, failedBranch string, skipped, done map[string]bool, completed []string) []string {
	completedSet := make(map[string]bool)
	for _, b := range completed {
		completedSet[b] = true
	}

	found := false
	var pending []string
	for _, entry := range sorted {
		if entry.Name == failedBranch {
			found = true
			continue
		}
		if found && !skipped[entry.Name] && !done[entry.Name] && !completedSet[entry.Name] {
			pending = append(pending, entry.Name)
		}
	}
	return pending
}

func collectSkippedNames(stack internal.Stack, branch string) []string {
	descs := internal.Descendants(stack, branch)
	var names []string
	for d := range descs {
		names = append(names, d)
	}
	return names
}

func resolveBase(base string) string {
	// If base is the repo's default branch, use its remote tracking ref
	defaultBranch := internal.DefaultBranch()
	if base == defaultBranch {
		return "origin/" + defaultBranch
	}
	return base
}

func markUpdatedAncestors(stack internal.Stack, branch string, featurePath string, updated map[string]bool) {
	entryMap := make(map[string]internal.StackEntry)
	for _, e := range stack.Branches {
		entryMap[e.Name] = e
	}

	current := branch
	for {
		entry, ok := entryMap[current]
		if !ok {
			break
		}
		parent, ok := entryMap[entry.Base]
		if !ok {
			break
		}
		parentPath := filepath.Join(featurePath, "worktrees", parent.Name)
		if _, err := os.Stat(parentPath); os.IsNotExist(err) {
			updated[parent.Name] = true
		}
		current = parent.Name
	}
}

func skipDescendants(stack internal.Stack, branch string, skipped map[string]bool) {
	descs := internal.Descendants(stack, branch)
	for d := range descs {
		skipped[d] = true
	}
	if len(descs) > 0 {
		fmt.Printf("    Skipping descendants: %s\n", internal.DescendantsList(stack, branch))
	}
}

func formatSyncStatus(name, mode, status string) string {
	symbols := map[string]string{
		"synced":            "+",
		"failed":            "x",
		"skipped":           "-",
		"conflict":          "!",
		"resolved":          "~",
		"wrong-branch":      "?",
		"validation-failed": "x",
	}
	sym := symbols[status]
	if sym == "" {
		sym = "?"
	}
	return fmt.Sprintf("  [%s] %s (%s)", sym, name, mode)
}

func syncFallback(featurePath string) {
	entries, _ := os.ReadDir(filepath.Join(featurePath, "worktrees"))
	for _, e := range entries {
		if !e.IsDir() {
			continue
		}
		path := filepath.Join(featurePath, "worktrees", e.Name())
		fmt.Printf("Syncing worktree: %s\n", path)
		internal.Must(internal.RunDirClean(path, "git", "rebase", "--update-refs", "origin/main"))
	}
}

// runValidation runs the configured test_command after a successful rebase.
func runValidation(worktreePath, branchName string) bool {
	cfg := internal.LoadConfig()
	if cfg.TestCommand == "" {
		return true
	}

	fmt.Printf("    validating %s: %s... ", branchName, cfg.TestCommand)
	parts := strings.Fields(cfg.TestCommand)
	err := internal.RunSilentDir(worktreePath, parts[0], parts[1:]...)
	if err != nil {
		fmt.Println("FAILED")
		fmt.Println(formatSyncStatus(branchName, "active", "validation-failed"))
		return false
	}
	fmt.Println("ok")
	return true
}

package internal

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
)

func RequireTool(name string) {
	if _, err := exec.LookPath(name); err != nil {
		fmt.Printf("Error: required tool %q not found in PATH\n", name)
		os.Exit(1)
	}
}

func MainRepoRoot() (string, error) {
	// git-common-dir returns the .git dir of the main repo even from a worktree.
	// In a non-worktree checkout it returns ".git" (relative).
	out, err := exec.Command("git", "rev-parse", "--git-common-dir").Output()
	if err != nil {
		return "", err
	}
	gitDir := strings.TrimSpace(string(out))

	if gitDir == ".git" {
		// Not inside a worktree — fall back to normal detection.
		return RepoRoot()
	}

	// gitDir is absolute (e.g. /path/to/repo/.git), resolve to parent.
	return filepath.Dir(filepath.Clean(gitDir)), nil
}

func RepoRoot() (string, error) {
	out, err := exec.Command("git", "rev-parse", "--show-toplevel").Output()
	if err != nil {
		return "", err
	}
	return strings.TrimSpace(string(out)), nil
}

func BranchExists(branch string) bool {
	err := exec.Command("git", "rev-parse", "--verify", branch).Run()
	return err == nil
}

// DefaultBranch returns the repo's default branch name (e.g., main, master).
// Detects from origin/HEAD, falls back to "main".
func DefaultBranch() string {
	out, err := exec.Command("git", "rev-parse", "--abbrev-ref", "origin/HEAD").Output()
	if err == nil {
		branch := strings.TrimSpace(string(out))
		// origin/HEAD returns "origin/main" — strip the "origin/" prefix
		if strings.HasPrefix(branch, "origin/") {
			return strings.TrimPrefix(branch, "origin/")
		}
		return branch
	}
	return "main"
}

// AbsPath returns the absolute path, resolving relative paths.
func AbsPath(path string) (string, error) {
	return filepath.Abs(path)
}

func Run(name string, args ...string) error {
	cmd := exec.Command(name, args...)
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	cmd.Stdin = os.Stdin

	return cmd.Run()
}

func RunDir(dir string, name string, args ...string) error {
	cmd := exec.Command(name, args...)
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	cmd.Stdin = os.Stdin
	cmd.Dir = dir

	return cmd.Run()
}

// RunDirClean runs a command in a directory, filtering git hint/warning noise
// from stderr. Actual errors are still shown.
func RunDirClean(dir string, name string, args ...string) error {
	return runWithFilteredStderr(dir, name, args...)
}

func runWithFilteredStderr(dir, name string, args ...string) error {
	cmd := exec.Command(name, args...)
	cmd.Stdout = os.Stdout
	cmd.Dir = dir

	stderr, err := cmd.StderrPipe()
	if err != nil {
		return err
	}

	if err := cmd.Start(); err != nil {
		return err
	}

	// Read stderr and filter
	buf := make([]byte, 4096)
	for {
		n, readErr := stderr.Read(buf)
		if n > 0 {
			lines := strings.Split(string(buf[:n]), "\n")
			for _, line := range lines {
				trimmed := strings.TrimSpace(line)
				if trimmed == "" {
					continue
				}
				// Filter git hint and advice lines
				if strings.HasPrefix(trimmed, "hint:") ||
					strings.HasPrefix(trimmed, "Disable this message") {
					continue
				}
				// Reformat cherry-pick skip warnings
				if strings.Contains(trimmed, "skipped previously applied commit") {
					fmt.Fprintf(os.Stderr, "    (skipped duplicate commit)\n")
					continue
				}
				fmt.Fprintln(os.Stderr, line)
			}
		}
		if readErr != nil {
			break
		}
	}

	return cmd.Wait()
}

func RunSilent(name string, args ...string) error {
	cmd := exec.Command(name, args...)
	return cmd.Run()
}

func RunSilentDir(dir string, name string, args ...string) error {
	cmd := exec.Command(name, args...)
	cmd.Dir = dir
	return cmd.Run()
}

// IsPrunableWorktree checks if a branch has a stale (prunable) worktree entry,
// meaning the directory was deleted but git still tracks it.
func IsPrunableWorktree(branch string) bool {
	out, err := exec.Command("git", "worktree", "list", "--porcelain").Output()
	if err != nil {
		return false
	}
	lines := strings.Split(string(out), "\n")
	for i, line := range lines {
		if strings.TrimSpace(line) == "branch refs/heads/"+branch {
			// Check surrounding lines in the same worktree block for "prunable"
			for j := i - 3; j <= i+2 && j < len(lines); j++ {
				if j < 0 {
					continue
				}
				if strings.HasPrefix(lines[j], "prunable") {
					return true
				}
			}
		}
	}
	return false
}

func Must(err error) {
	if err != nil {
		fmt.Println("Error:", err)
		os.Exit(1)
	}
}
